using Server.Items;
namespace Server.UOOffline;
internal static class HavenShadowScenery
{
    internal static void Build(HavenShadowChamber chamber)
    {
        var data = chamber.Room switch { HavenShadowRoom.Bar => Bar, HavenShadowRoom.Orchard => Orchard, HavenShadowRoom.Armory => Armory, HavenShadowRoom.Fountain => Fountain, HavenShadowRoom.Belfry => Belfry, _ => null };
        if (data == null) { return; }
        for (var i = 0; i < data.GetLength(0); i++)
        {
            var item = new Static(data[i, 0]);
            item.MoveToWorld(new Point3D(chamber.X - 1 + data[i, 1], chamber.Y - 1 + data[i, 2], chamber.Z + data[i, 3]), chamber.Map);
            chamber.Fixtures.Add(item);
        }
    }
